function appendFailedSummary(provider: string | null, reason: string | null): HostRunUsageSummary {
  return {
    recorded: 'none',
    provider,
    input: null,
    cacheRead: null,
    output: null,
    recordId: null,
    reason: reason && reason.length > 0 ? reason : 'ledger_append_failed(unknown)',
  };
}

